import{_ as a,o as t,c as n,a5 as r}from"./chunks/framework.pJebtgMf.js";const u=JSON.parse('{"title":"AI 动态 · 2026-08-27","description":"","frontmatter":{"title":"AI 动态 · 2026-08-27","date":"2026-08-27T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-08/ai-news-2026-08-27.md","filePath":"news/2026-08/ai-news-2026-08-27.md","lastUpdated":null}'),s={name:"news/2026-08/ai-news-2026-08-27.md"};function i(o,e,c,p,l,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-动态-·-2026-08-27" tabindex="-1">AI 动态 · 2026-08-27 <a class="header-anchor" href="#ai-动态-·-2026-08-27" aria-label="Permalink to &quot;AI 动态 · 2026-08-27&quot;">​</a></h1><blockquote><p>截至 2026-08-27。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="英伟达拟-129-亿美元收购-hugging-face-巩固芯片帝国并重返云业务" tabindex="-1">英伟达拟 129 亿美元收购 Hugging Face，巩固芯片帝国并重返云业务 <a class="header-anchor" href="#英伟达拟-129-亿美元收购-hugging-face-巩固芯片帝国并重返云业务" aria-label="Permalink to &quot;英伟达拟 129 亿美元收购 Hugging Face，巩固芯片帝国并重返云业务&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-27">2026-08-27</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/4935eab4d0c1.jpg" alt="配图"></p><p>据报道，英伟达已同意以 129 亿美元收购开源 AI 中心 Hugging Face。此举既是为了保护其芯片业务生态，也是重返云业务的重要布局。收购若完成，将深刻影响 AI 模型分发与开源社区格局。对读者：关注 Hugging Face 平台后续的开放性及定价策略变化，评估对自身模型工作流的影响。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/26/nvidia-closes-in-on-hugging-face-acquisition/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="openai-将在印度-chatgpt-免费版及-go-套餐中展示广告" tabindex="-1">OpenAI 将在印度 ChatGPT 免费版及 Go 套餐中展示广告 <a class="header-anchor" href="#openai-将在印度-chatgpt-免费版及-go-套餐中展示广告" aria-label="Permalink to &quot;OpenAI 将在印度 ChatGPT 免费版及 Go 套餐中展示广告&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-27">2026-08-27</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/fb3a2b9336e9.jpg" alt="配图"></p><p>OpenAI 宣布将在印度市场的 ChatGPT 免费版和低价 Go 套餐中开始展示广告。印度是 ChatGPT 周活跃用户超 1 亿的重要市场，其中大部分用户使用免费或低价套餐。此举是 OpenAI 探索广告变现模式的重要一步。对读者：关注广告模式对用户体验和 API 商业策略的潜在影响。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/27/openai-to-start-showing-ads-on-chatgpts-free-and-go-tiers-in-india/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="minimax-arr-暴涨-500-超-8-亿美元-b-端收入占比升至-80" tabindex="-1">MiniMax ARR 暴涨 500% 超 8 亿美元，B 端收入占比升至 80% <a class="header-anchor" href="#minimax-arr-暴涨-500-超-8-亿美元-b-端收入占比升至-80" aria-label="Permalink to &quot;MiniMax ARR 暴涨 500% 超 8 亿美元，B 端收入占比升至 80%&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-08-27">2026-08-27</time></p><p>MiniMax 最新数据显示，截至 2026 年 8 月，公司年度经常性收入（ARR）已超过 8 亿美元，较 2 月的 1.5 亿美元增长超 500%。2026 年上半年收入达 1.166 亿美元，同比增长 283%，其中 B 端收入占比从去年约三成快速提升至 80%。对读者：MiniMax 的增长重心已从 C 端转向企业服务，其商业化路径对 AI 应用创业者有参考价值。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/08/480092.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="hugging-face-推出-399-美元开源鸭子机器人-microduck" tabindex="-1">Hugging Face 推出 399 美元开源鸭子机器人 Microduck <a class="header-anchor" href="#hugging-face-推出-399-美元开源鸭子机器人-microduck" aria-label="Permalink to &quot;Hugging Face 推出 399 美元开源鸭子机器人 Microduck&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-27">2026-08-27</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/1eba656ab4ed.jpg" alt="配图"></p><p>Hugging Face 旗下 Pollen Robotics 推出第二款机器人 Microduck，这是一款高约 10 英寸的单眼双足机器人，支持开源，可通过强化学习教它新技巧。现已开放预购，售价 399 美元，有四种颜色可选，计划在 2026 年圣诞节前发货。对读者：开源硬件与 AI 结合的新玩具，适合开发者用于学习机器人控制和强化学习。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/27/hugging-face-is-selling-a-cute-399-open-source-duck-robot-microduck/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="adobe-为-photoshop-增加更多-ai-功能-推出全新-ai-辅助编辑器界面" tabindex="-1">Adobe 为 Photoshop 增加更多 AI 功能，推出全新 AI 辅助编辑器界面 <a class="header-anchor" href="#adobe-为-photoshop-增加更多-ai-功能-推出全新-ai-辅助编辑器界面" aria-label="Permalink to &quot;Adobe 为 Photoshop 增加更多 AI 功能，推出全新 AI 辅助编辑器界面&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-08-27">2026-08-27</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/dc0f914009fb.jpg" alt="配图"></p><p>Adobe 正在为 Photoshop 推送一个 AI 重头更新，包括一个可选的「AI 辅助编辑器」界面，将提示词图像编辑、背景移除、AI 图像扩展等功能整合到单一工具栏。此外还新增了「标记」功能，用户可直接在图像上绘制以指示 AI 助手进行修改。对读者：Photoshop 的 AI 化操作门槛进一步降低，设计师可关注 Beta 版体验。</p><p class="news-entry-source"><a href="https://www.theverge.com/tech/985491/adobe-photoshop-ai-assisted-editor-markup" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="deepseek-估值有望达-740-亿美元" tabindex="-1">DeepSeek 估值有望达 740 亿美元 <a class="header-anchor" href="#deepseek-估值有望达-740-亿美元" aria-label="Permalink to &quot;DeepSeek 估值有望达 740 亿美元&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">WSJ</span><time datetime="2026-08-27">2026-08-27</time></p><p>据 WSJ 报道，AI 初创公司 DeepSeek 正接近达成 740 亿美元的估值。这一估值水平使其跻身全球最具价值的 AI 公司之列，反映了市场对其模型能力和开源策略的高度认可。对读者：DeepSeek 的崛起将持续影响开源模型竞争格局，值得关注其后续技术路线。</p><p class="news-entry-source"><a href="https://news.google.com/rss/articles/CBMimAFBVV95cUxNN2ZVcER1YXNsaEthelVtNENlUXBCMzdyRV80bWhNWHBHSk5rVmMzZGJyaFZfWS1YclBDWklqc0RFTEZzYm1fSXJzd1RWVDR4U1d2QzZfWTRFTUtfa1Ewa2FBUzRGZU93dkE4dWZJM0YwdHFhaWlrLTF2ajRBaWt2TGZMS1oyclVaM0lpQms1dGx1T3JTVlFLdA?oc=5" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="谷歌发布-gemini-3-5-transcribe-提供更智能的语音转文字能力" tabindex="-1">谷歌发布 Gemini 3.5 Transcribe，提供更智能的语音转文字能力 <a class="header-anchor" href="#谷歌发布-gemini-3-5-transcribe-提供更智能的语音转文字能力" aria-label="Permalink to &quot;谷歌发布 Gemini 3.5 Transcribe，提供更智能的语音转文字能力&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Google DeepMind</span><time datetime="2026-08-27">2026-08-27</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/48abe8e53e0d.jpg" alt="配图"></p><p>Google DeepMind 推出 Gemini 3.5 Transcribe，这是一款更智能的语音转文字（speech-to-text）模型。该技术此前已驱动 Gboard 的 Rambler 功能，现在将扩展至更多 Google 产品，包括 Chrome 浏览器。对读者：语音交互体验有望在 Chrome 等常用工具中显著提升，开发者可关注相关 API 的开放进度。</p><p class="news-entry-source"><a href="https://deepmind.google/blog/intelligent-transcription-with-gemini-3-5-transcribe/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="千问办公首发上线-qwen3-8-flash-生成速度提升-100" tabindex="-1">千问办公首发上线 Qwen3.8-Flash，生成速度提升 100% <a class="header-anchor" href="#千问办公首发上线-qwen3-8-flash-生成速度提升-100" aria-label="Permalink to &quot;千问办公首发上线 Qwen3.8-Flash，生成速度提升 100%&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-08-27">2026-08-27</time></p><p>千问办公首发上线 Qwen3.8-Flash 模型，并推出标准模式。该模型以千亿级总参数实现超越 Claude Opus 4.6 的性能，通过 Agent 协同优化，在真实办公场景中单任务生成速度提升约 100%，Token 消耗平均减少 75%。对读者：办公场景下高性能与低成本兼得成为可能，可关注其标准模式的积分消耗策略。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/08/480001.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><p>（本日无新条目）</p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="azure-devops-remote-mcp-服务器正式发布-暂不支持-claude-和-chatgpt" tabindex="-1">Azure DevOps Remote MCP 服务器正式发布，暂不支持 Claude 和 ChatGPT <a class="header-anchor" href="#azure-devops-remote-mcp-服务器正式发布-暂不支持-claude-和-chatgpt" aria-label="Permalink to &quot;Azure DevOps Remote MCP 服务器正式发布，暂不支持 Claude 和 ChatGPT&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-27">2026-08-27</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/fc05aa7d2b15.jpg" alt="配图"></p><p>微软正式推出 Azure DevOps Remote MCP 服务器，为 AI 助手提供托管端点，可直接访问工作项、PR、代码库和流水线，无需本地部署。不过目前 Claude Desktop、Claude Code、ChatGPT 和 Cursor 尚无法连接，问题出在微软内部而非客户端。对读者：MCP 生态持续扩展，但跨厂商兼容性仍是落地障碍，需关注后续适配进展。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/SvTBvljtvGctvWPQRqr7?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="github-copilot-应用教程-自动化-dependabot-拉取请求分类" tabindex="-1">GitHub Copilot 应用教程：自动化 Dependabot 拉取请求分类 <a class="header-anchor" href="#github-copilot-应用教程-自动化-dependabot-拉取请求分类" aria-label="Permalink to &quot;GitHub Copilot 应用教程：自动化 Dependabot 拉取请求分类&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">GitHub Blog</span><time datetime="2026-08-27">2026-08-27</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/2536ba5ce144.png" alt="配图"></p><p>GitHub 官方博客发布教程，介绍如何使用 GitHub Copilot 应用来自动化处理 Dependabot 拉取请求的分类工作。该教程面向初学者，展示了如何利用 Copilot 处理重复性的库更新管理任务，提升开发效率。对读者：可参考该教程将 Copilot 应用于日常依赖维护，减少手动分类的繁琐操作。</p><p class="news-entry-source"><a href="https://github.blog/ai-and-ml/github-copilot/github-copilot-app-for-beginners-automate-dependabot-pull-request-triage/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="使用-document-picture-in-picture-api-创建-web-组件" tabindex="-1">使用 Document Picture-in-Picture API 创建 Web 组件 <a class="header-anchor" href="#使用-document-picture-in-picture-api-创建-web-组件" aria-label="Permalink to &quot;使用 Document Picture-in-Picture API 创建 Web 组件&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">CSS-Tricks</span><time datetime="2026-08-27">2026-08-27</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/13d5db81168f.png" alt="配图"></p><p>CSS-Tricks 发布教程，介绍如何使用 Document Picture-in-Picture API 创建 Web 组件。该 API 允许开发者创建一个独立的画中画窗口，并在其中放入 HTML、CSS 和 JavaScript，Firefox 151 已支持此功能。对读者：该 API 为构建多窗口 Web 应用提供了新思路，前端开发者可探索其应用场景。</p><p class="news-entry-source"><a href="https://css-tricks.com/creating-web-widgets-using-the-document-picture-in-picture-api/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div>',8)])])}const m=a(s,[["render",i]]);export{u as __pageData,m as default};
